import SwiftUI

/// Shows a legal / info document (Privacy Policy, Terms, About Us). The text lives in
/// LegalContent.swift, which is generated by Tools/generate_legal.py so the app and the
/// website pages always match.
struct LegalDocumentView: View {
    let title: String
    let updated: String?
    let sections: [LegalSection]
    var showsBrand = false

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 20) {
                if showsBrand {
                    HStack {
                        Spacer()
                        VStack(spacing: 8) {
                            BrandMark(size: 72)
                            Text("Pitchsong by Blunt Entertainment")
                                .appFont(13, weight: .semibold)
                                .foregroundColor(Theme.muted)
                        }
                        Spacer()
                    }
                    .padding(.top, 4)
                }

                VStack(alignment: .leading, spacing: 4) {
                    Text(title)
                        .appFont(30, weight: .black, design: .rounded)
                        .foregroundColor(Theme.text)
                    if let updated {
                        Text("Last updated: \(updated)")
                            .appFont(13)
                            .foregroundColor(Theme.muted)
                    }
                }

                ForEach(sections, id: \.heading) { section in
                    VStack(alignment: .leading, spacing: 8) {
                        Text(section.heading)
                            .appFont(17, weight: .bold)
                            .foregroundColor(Theme.amberText)
                        ForEach(section.paragraphs, id: \.self) { paragraph in
                            Text(paragraph)
                                .appFont(14.5)
                                .foregroundColor(Theme.text.opacity(0.9))
                                .fixedSize(horizontal: false, vertical: true)
                        }
                        ForEach(section.bullets, id: \.self) { bullet in
                            HStack(alignment: .top, spacing: 8) {
                                Text("•")
                                    .appFont(14.5, weight: .bold)
                                    .foregroundColor(Theme.magentaText)
                                Text(bullet)
                                    .appFont(14.5)
                                    .foregroundColor(Theme.text.opacity(0.9))
                                    .fixedSize(horizontal: false, vertical: true)
                            }
                        }
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                }
            }
            .padding(.horizontal, 18)
            .padding(.top, 8)
            .padding(.bottom, 40)
            .readableWidth(720)
        }
        .background(AppBackground())
        .navigationTitle(title)
        .navigationBarTitleDisplayMode(.inline)
        .toolbar(.visible, for: .navigationBar)
    }
}

struct ContactUsView: View {
    @Environment(\.openURL) private var openURL
    @State private var showFreeForm = false

    private var emailURL: URL? {
        URL(string: "mailto:\(Contact.email)?subject=Pitchsong%20support")
    }

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 18) {
                ScreenHeader(
                    kicker: "Get in touch",
                    title: "Contact us",
                    subtitle: "Questions about packages, orders or the app? Message the Blunt Entertainment team."
                )

                VStack(spacing: 0) {
                    Button {
                        openURL(Contact.whatsappGeneralLink)
                    } label: {
                        InfoRow(icon: "message.fill", color: Color(hex: 0x25D366),
                                title: "WhatsApp", subtitle: Contact.whatsappDisplay)
                    }
                    .buttonStyle(.plain)
                    Divider().overlay(Theme.line)
                    Button {
                        if let emailURL { openURL(emailURL) }
                    } label: {
                        InfoRow(icon: "envelope.fill", color: Theme.cyanText,
                                title: "Email", subtitle: Contact.email)
                    }
                    .buttonStyle(.plain)
                    Divider().overlay(Theme.line)
                    Button {
                        openURL(Contact.instagramURL)
                    } label: {
                        InfoRow(icon: "camera.fill", color: Theme.magentaText,
                                title: "Instagram", subtitle: Contact.instagramHandle)
                    }
                    .buttonStyle(.plain)
                    Divider().overlay(Theme.line)
                    Button {
                        showFreeForm = true
                    } label: {
                        InfoRow(icon: "gift.fill", color: Theme.amberText,
                                title: "Free song submission", subtitle: "Placement is not guaranteed")
                    }
                    .buttonStyle(.plain)
                }
                .card(padding: 4)

                ForEach(LegalContent.support.filter { $0.bullets.isEmpty }, id: \.heading) { section in
                    VStack(alignment: .leading, spacing: 6) {
                        Text(section.heading)
                            .appFont(16, weight: .bold)
                            .foregroundColor(Theme.amberText)
                        ForEach(section.paragraphs, id: \.self) { paragraph in
                            Text(paragraph)
                                .appFont(14)
                                .foregroundColor(Theme.muted)
                                .fixedSize(horizontal: false, vertical: true)
                        }
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                }

                Text("Blunt Entertainment · Nigeria")
                    .appFont(12)
                    .foregroundColor(Theme.faint)
                    .frame(maxWidth: .infinity)
                    .padding(.top, 4)
            }
            .padding(.horizontal, 16)
            .padding(.top, 8)
            .padding(.bottom, 32)
            .readableWidth(640)
        }
        .background(AppBackground())
        .navigationTitle("Contact Us")
        .navigationBarTitleDisplayMode(.inline)
        .toolbar(.visible, for: .navigationBar)
        .sheet(isPresented: $showFreeForm) {
            SafariView(url: Contact.freeSubmissionURL)
                .ignoresSafeArea()
        }
    }
}
